_helper_glances_modules() {
    _argc_util_cache 3600 _helper_glances_modules_raw | gawk -v section="$1" '
        index(tolower($0), section " list:") == 1 {
            sub(/^[^:]*:[ \t]*/, "")
            count = split($0, items, ",")
            for (i = 1; i <= count; i++) {
                gsub(/^[ \t]+|[ \t]+$/, "", items[i])
                if (items[i] != "") {
                    print items[i]
                }
            }
            exit
        }
    '
}

